<div class="mx-auto max-w-5xl px-4 py-8"><h1 class="text-3xl font-bold text-slate-900">Website enquiries</h1><p class="mt-2 text-slate-600">Restricted platform support inbox. Respond through your approved support channel. Closing a message retains its contents.</p><nav class="my-6 flex gap-3" aria-label="Inbox status"><a href="<?php echo e(route('admin.contact.index')); ?>" class="rounded-xl border px-4 py-3 <?php echo e($status === 'open' ? 'bg-indigo-700 text-white' : 'bg-white'); ?>">Open</a><a href="<?php echo e(route('admin.contact.index', ['status' => 'closed'])); ?>" class="rounded-xl border px-4 py-3 <?php echo e($status === 'closed' ? 'bg-indigo-700 text-white' : 'bg-white'); ?>">Closed</a></nav><?php if(session('success')): ?><p role="status" class="mb-4 rounded-xl bg-emerald-50 p-4 text-emerald-900"><?php echo e(session('success')); ?></p><?php endif; ?>
